SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @SW bigint=(SELECT s.NumWrites-b.NumWrites FROM lab.Evidence s CROSS JOIN lab.Evidence b WHERE s.Stage='SINGLE_COMMIT' AND b.Stage='BASELINE'),@BW bigint=(SELECT s.NumWrites-b.NumWrites FROM lab.Evidence s CROSS JOIN lab.Evidence b WHERE s.Stage='BATCH_COMMIT' AND b.Stage='BATCH_BASELINE'),@SR bigint=(SELECT ResultRows FROM lab.Evidence WHERE Stage='SINGLE_COMMIT'),@BR bigint=(SELECT ResultRows FROM lab.Evidence WHERE Stage='BATCH_COMMIT'),@SC int=(SELECT ResultChecksum FROM lab.Evidence WHERE Stage='SINGLE_COMMIT'),@BC int=(SELECT ResultChecksum FROM lab.Evidence WHERE Stage='BATCH_COMMIT');IF @SR<>4000 OR @BR<>4000 OR @SC<>@BC THROW 51006,'FAIL_RESULT_CONTRACT: Commitmuster sind nicht ergebnisgleich.',1;SELECT @SW SingleCommitWrites,@BW BatchCommitWrites;IF @BW>=@SW BEGIN PRINT 'SQLPERF_SUMMARY|WARN|WARN_EMPIRICAL_VARIANCE';RETURN;END;PRINT 'SQLPERF_SUMMARY|PASS|OK';
